action.command:
cat << 'EOF'
import json, sys
# Check if writing to protected files
protected = [".env", "secrets.json", "passwords.txt"]
file_paths = ["$FILE_PATH"] if "$FILE_PATH" else []
for f in file_paths:
    if any(p in f for p in protected):
        print(json.dumps({
            "hookSpecificOutput": {
                "permissionDecision": "ask",
                "permissionDecisionReason": f"Writing to protected file: {f}. Confirm you want to proceed?"
            }
        }))
        sys.exit(0)
print(json.dumps({"hookSpecificOutput": {"permissionDecision": "allow"}}))
EOF
